{
  "name": "range-to-regex",
  "version": "1.0.0",
  "description": "Convert a numeric range like \"1-100\" into a single regular expression that matches any number in that range.",
  "main": "index.js",
  "scripts": {
    "test": "node test.js"
  },
  "keywords": [
    "regex",
    "regexp",
    "range",
    "regular-expression"
  ],
  "license": "MIT",
  "dependencies": {
    "to-regex-range": "^5.0.1"
  }
}

'use strict';

const toRegexRange = require('to-regex-range');

const RANGE_RE = /^(-?\d+)-(-?\d+)$/;

function parseRange(range) {
  if (typeof range !== 'string') {
    throw new TypeError('Expected range to be a string, e.g. "1-100"');
  }

  const match = RANGE_RE.exec(range.trim());
  if (!match) {
    throw new TypeError(`Invalid numeric range: ${JSON.stringify(range)}`);
  }

  return { min: Number(match[1]), max: Number(match[2]) };
}

function rangeToRegex(range, options) {
  const { min, max } = parseRange(range);
  return toRegexRange(min, max, options);
}

function rangeToRegExp(range, options) {
  const { min, max } = parseRange(range);
  return new RegExp(`^(?:${toRegexRange(min, max, options)})$`);
}

module.exports = rangeToRegex;
module.exports.rangeToRegex = rangeToRegex;
module.exports.rangeToRegExp = rangeToRegExp;
module.exports.parseRange = parseRange;

'use strict';

const assert = require('assert');
const rangeToRegex = require('./index');
const { rangeToRegExp } = require('./index');

assert.strictEqual(rangeToRegex('1-100'), '[1-9]|[1-9][0-9]|100');

const re = rangeToRegExp('1-100');
assert.ok(re.test('1'));
assert.ok(re.test('50'));
assert.ok(re.test('100'));
assert.ok(!re.test('0'));
assert.ok(!re.test('101'));
assert.ok(!re.test('1.5'));

const single = rangeToRegExp('5-5');
assert.ok(single.test('5'));
assert.ok(!single.test('4'));

const negative = rangeToRegExp('-10--1');
assert.ok(negative.test('-10'));
assert.ok(negative.test('-1'));
assert.ok(!negative.test('0'));

assert.throws(() => rangeToRegex('abc'), /Invalid numeric range/);

console.log('All tests passed');

